	"cli.config.help":
		"{{title}} - Manage settings\n\n{{headingCommands}}\n  list               List all settings with current values\n  get <key>          Get a specific setting value\n  set <key> <value>  Set a setting value\n  reset <key>        Remove a setting from config.yml so its default applies\n  path               Print the config directory path\n  init-xdg           Initialize XDG Base Directory structure\n\n{{headingOptions}}\n  --json             Output as JSON\n\n{{headingExamples}}\n  {{app}} config list\n  {{app}} config get theme\n  {{app}} config set theme catppuccin-mocha\n  {{app}} config set compaction.enabled false\n  {{app}} config set defaultThinkingLevel medium\n  {{app}} config reset steeringMode\n  {{app}} config list --json\n  {{app}} config init-xdg\n\n{{headingBooleanValues}}\n  true, false, yes, no, on, off, 1, 0\n",
	"cli.grep.help":
		'{{title}} - Test grep tool\n\n{{headingUsage}}\n  {{app}} grep <pattern> [path] [options]\n\n{{headingArguments}}\n  pattern   Regex pattern to search for\n  path      Directory or file to search (default: .)\n\n{{headingOptions}}\n  -g, --glob <pattern>  Filter files by glob pattern\n  -l, --limit <n>       Max matches (default: 20)\n  -C, --context <n>     Context lines (default: 2)\n  -f, --files           Output file names only\n  -c, --count           Output match counts per file\n  -h, --help            Show this help\n  --no-gitignore        Include files excluded by .gitignore\n\n{{headingEnvironment}}\n  PI_WALK_WORKERS=N    Set filesystem walker workers (default 4, 0 = auto)\n\n{{headingExamples}}\n  {{app}} grep "import" src/\n  {{app}} grep "TODO" . --glob "*.ts"\n  {{app}} grep "function" --files\n',
	"cli.plugin.help":
		"{{title}} - Plugin lifecycle management\n\n{{headingCommands}}\n  install <source>[features]     Install plugins from npm, GitHub, or git URL\n  uninstall <pkg>                Remove plugins\n  list                           Show installed plugins\n  link <path>                    Link local plugin for development\n  doctor                         Check plugin health\n  features <pkg>                 View/modify enabled features\n  config <cmd> <pkg> [key] [val] Manage plugin settings\n  enable <pkg>                   Enable a disabled plugin\n  disable <pkg>                  Disable plugin without uninstalling\n  marketplace <cmd>            Manage marketplace sources (add, remove, update, list)\n  discover [marketplace]        Browse available marketplace plugins\n\n{{headingFeatureSyntax}}\n  pkg                Install with default features\n  pkg[feat1,feat2]   Install with specific features\n  pkg[*]             Install with all features\n  pkg[]              Install with no optional features\n\n{{headingSources}}\n  pkg, pkg@1.2.3                  npm package (optionally pinned)\n  github:user/repo[#ref]          GitHub shorthand (also gitlab:, bitbucket:, codeberg:, sourcehut:)\n  https://github.com/user/repo    Full git URL (https, ssh, or git protocol)\n  name@marketplace                Marketplace plugin (see marketplace command)\n  ./path, ../path, /abs, ~/path   Local plugin directory (symlinked, same as plugin link)\n\n{{headingConfigSubcommands}}\n  config list <pkg>              List all settings\n  config get <pkg> <key>         Get a setting value\n  config set <pkg> <key> <val>   Set a setting value\n  config delete <pkg> <key>      Delete a setting\n  config validate                Validate all plugin settings\n\n{{headingOptions}}\n  --json           Output as JSON\n  --fix            Attempt automatic fixes (doctor)\n  --force          Overwrite without prompting (install)\n  --scope <scope>  Install scope: user (default) or project (install name@marketplace)\n  --dry-run        Preview changes without applying (install)\n  -l, --local      Use project-local overrides\n\n{{headingExamples}}\n  {{app}} plugin install @oh-my-pi/exa[search]\n  {{app}} plugin list --json\n  {{app}} plugin features my-plugin --enable search,web\n  {{app}} plugin config set my-plugin apiKey sk-xxx\n  {{app}} plugin doctor --fix\n  {{app}} plugin install --scope project name@marketplace\n  {{app}} plugin install github:user/repo#v1.0\n",
	"cli.setup.help":
		"{{title}} - Run onboarding or install dependencies for optional features\n\n{{headingUsage}}\n  {{app}} setup                     Run the onboarding wizard\n  {{app}} setup <component> [options]\n\n{{headingComponents}}\n  python    Verify a Python 3 interpreter is reachable for code execution\n  speech    Pick and download speech-to-text and text-to-speech models\n\n{{headingOptions}}\n  -c, --check   Check if dependencies are installed without installing\n  --json        Output status as JSON\n\n{{headingExamples}}\n  {{app}} setup                  Run the onboarding wizard\n  {{app}} setup python           Check Python execution dependencies\n  {{app}} setup speech           Pick and download the STT and TTS models\n  {{app}} setup speech --check   Check if speech dependencies are available\n  {{app}} setup python --check   Check if Python execution is available\n",
	"cli.shell.help":
		"{{title}} - Interactive shell console for testing\n\n{{headingUsage}}\n  {{app}} shell [options]\n\n{{headingOptions}}\n  --cwd, -C <path>     Set working directory for commands\n  --timeout, -t <ms>   Timeout per command in milliseconds\n  --no-snapshot        Skip sourcing snapshot from user shell\n  -h, --help           Show this help\n\n{{headingExamples}}\n  {{app}} shell\n  {{app}} shell --cwd ./tmp\n  {{app}} shell --timeout 2000\n",
	"cli.update.help":
		"{{title}} - Check for and install updates\n\n{{headingUsage}}\n  {{app}} update [options]\n\n{{headingOptions}}\n  -c, --check     Check for updates without installing\n  -f, --force     Force reinstall even if up to date\n  -l, --plugins   Update installed plugins\n  --canary        Switch to the canary channel and update\n  --stable        Switch back to the stable channel\n\n{{headingExamples}}\n  {{app}} update              Update to latest version\n  {{app}} update --check      Check if updates are available\n  {{app}} update --force      Force reinstall\n  {{app}} update -l           Update installed plugins\n  {{app}} update --canary    Switch to the canary channel and update\n",
	"cli.webSearch.help":
		'{{title}} - Test web search models\n\n{{headingUsage}}\n  {{app}} q [options] <query>\n  {{app}} web-search [options] <query>\n\n{{headingArguments}}\n  query      Search query text\n\n{{headingOptions}}\n  --model <selector>  Catalog model selector (for example, web/duckduckgo)\n  --recency <value>   Recency filter (when supported): {{recency}}\n  -l, --limit <n>     Max results to return\n  --compact           Render condensed output\n  -h, --help          Show this help\n\n{{headingQueryDirectives}}\n  site:/-site:  after:/before: (YYYY-MM-DD)  inurl:  intitle:  filetype:\n  "exact phrase"  -term  OR\n  Mapped to native provider filters where available, otherwise applied as a\n  lenient post-filter (a constraint matching nothing is relaxed, not fatal).\n\n{{headingExamples}}\n  {{app}} q --model=web/duckduckgo "what\'s the color of the sky"\n  {{app}} q --model=openrouter/google/gemini-2.5-flash --recency=week "latest TypeScript changes"\n  {{app}} q \'transformer scaling site:arxiv.org after:2024 -site:reddit.com\'\n',
